// Paginate returns a page of orders with total count for offset-based pagination.
// A nil filter paginates all orders.
func (c *orderClient) Paginate(ctx context.Context, input PaginateInput[OrderFilter], opts ...func(*CallOptions[OrderFieldOptions])) (*PaginateResult[Order], error) {
	options := resolveCallOptions(opts)
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpPaginate, Table: TableOrders, Schema: "",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[OrderFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Total count (delegates to Count — both are always generated)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate orders count: %w", err)
		}

		// Page data via GetMany (handles FieldOptions and relationships)
		orders, err := c.GetMany(ctx, &GetOrdersInput{
			Filter: input.Filter,
			Sorts:  input.Sort,
			Limit:  &input.Limit,
			Offset: &input.Offset,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate orders: %w", err)
		}

		return &PaginateResult[Order]{
			Items:      orders,
			TotalCount: totalCount,
			Offset:     input.Offset,
			Limit:      input.Limit,
			HasMore:    int64(input.Offset+input.Limit) < totalCount,
		}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*PaginateResult[Order]), nil
}

// Connection returns a Relay-style cursor-paginated connection of orders.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
func (c *orderClient) Connection(ctx context.Context, input ConnectionInput[OrderFilter], opts ...func(*CallOptions[OrderFieldOptions])) (*Connection[Order], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("connection orders: LockMode requires an active transaction")
		}
		options.SkipCache = true
		if options.LockMode == sql.LockForUpdateNoWait || options.LockMode == sql.LockForUpdateSkipLocked {
			version, err := c.mysqlVersion.get(ctx)
			if err != nil {
				return nil, fmt.Errorf("connection orders: %w", err)
			}
			if version.Major < 8 {
				return nil, fmt.Errorf("connection orders: LockMode %s requires MySQL 8.0+ (server reports %s)", options.LockMode, version.Raw)
			}
		}
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableOrders, Schema: "",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[OrderFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection orders count: %w", err)
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeCursor(*input.After)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeCursor(*input.Before)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		orders, err := c.GetMany(ctx, &GetOrdersInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection orders: %w", err)
		}

		// Trim extra row and determine page boundaries
		hasMore := len(orders) > limit
		if hasMore {
			orders = orders[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(orders)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[Order], len(orders))
		for i, row := range orders {
			cursor, err := encodeOrderCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[Order]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[Order]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*Connection[Order]), nil
}

// encodeOrderCursor encodes cursor key values as a base64 JSON string.
func encodeOrderCursor(keys []string, o *Order) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "id":
			out["id"] = o.ID
		case "user_id":
			out["user_id"] = o.UserID
		case "status":
			out["status"] = o.Status
		case "total":
			out["total"] = o.Total
		case "notes":
			out["notes"] = o.Notes
		case "ordered_at":
			out["ordered_at"] = o.OrderedAt
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode order cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

