// scanUserEvents scans rows into UserEvent entities using a column-name switch.
// Handles both scan target shapes (direct, wrapped) without reflection.
func scanUserEvents(rows database.Rows, columns []string) ([]*UserEvent, error) {
	var result []*UserEvent
	for rows.Next() {
		u := &UserEvent{}

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "id":
				targets[idx] = &u.ID
			case "user_id":
				targets[idx] = &u.UserID
			case "action":
				targets[idx] = &u.Action
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan user_event: %w", err)
		}

		result = append(result, u)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate user_event rows: %w", err)
	}
	return result, nil
}

