// CreateWarehouseInput holds the fields for creating a warehouses record.
type CreateWarehouseInput struct {
	// ExternalID - External reference ID (KSUID)
	ExternalID ksuid.KSUID `json:"external_id"`
	// Name - Warehouse name
	Name string `json:"name"`
	// Price - Operational cost
	Price decimal.Decimal `json:"price"`
	// NullablePrice - Optional secondary price
	NullablePrice omittable.Value[decimal.NullDecimal] `json:"nullable_price,omitzero"`
	// CreatedAt - Row creation timestamp
	CreatedAt omittable.Value[time.Time] `json:"created_at,omitzero"`
}

// UpdateWarehouseInput holds the fields for updating a warehouses record.
// All fields use omittable.Value to distinguish "not set" from "set to zero".
type UpdateWarehouseInput struct {
	// ExternalID - External reference ID (KSUID)
	ExternalID omittable.Value[ksuid.KSUID] `json:"external_id,omitzero"`
	// Name - Warehouse name
	Name omittable.Value[string] `json:"name,omitzero"`
	// Price - Operational cost
	Price omittable.Value[decimal.Decimal] `json:"price,omitzero"`
	// NullablePrice - Optional secondary price
	NullablePrice omittable.Value[decimal.NullDecimal] `json:"nullable_price,omitzero"`
	// CreatedAt - Row creation timestamp
	CreatedAt omittable.Value[time.Time] `json:"created_at,omitzero"`
}

// GetWarehousesInput holds query parameters for retrieving warehouses records.
// Field selection is controlled via CallOptions.FieldOptions, not this struct.
type GetWarehousesInput struct {
	Filter *WarehouseFilter `json:"filter"`
	Limit  *int             `json:"limit"`
	Offset *int             `json:"offset"`
	Sorts  []sql.Sort       `json:"sorts"`
	// conditions holds additional SQL conditions injected by internal callers
	// (e.g., Connection keyset conditions). Not part of the public API.
	conditions []sql.Condition
	// requiredColumns holds columns an internal caller needs read back even
	// when FieldOptions narrows the projection (e.g., Connection cursor keys).
	// Not part of the public API.
	requiredColumns []string
}
